package com.cvns.service;import java.time.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.cvns.dtos.ResponseDtos.ReportResponse;import com.cvns.entities.*;import com.cvns.entities.AppEnums.VaccinationStatus;import com.cvns.repository.*;import lombok.RequiredArgsConstructor;
@Service @Transactional(readOnly=true) @RequiredArgsConstructor public class ReportService{private final ClinicService clinics;private final VaccinationRecordRepository records;private final AppointmentRepository apps;public ReportResponse report(String period){Clinic c=clinics.current();LocalDate to=LocalDate.now(),from="monthly".equalsIgnoreCase(period)?to.withDayOfMonth(1):to;return new ReportResponse(from,to,records.countByClinicIdAndStatusAndCompletedDateBetween(c.getId(),VaccinationStatus.COMPLETED,from,to),records.countByClinicIdAndStatus(c.getId(),VaccinationStatus.PENDING),apps.countByClinicIdAndAppointmentDateBetween(c.getId(),from,to),records.countDistinctCompletedChildren(c.getId(),VaccinationStatus.COMPLETED,from,to));}}
